\begin{algorithmic}[1]
\State \textbf{Input:} Initial parameters $w_0$, learning rate $\eta$, weight decay $\lambda$, parameters $\beta_1, \beta_2, \epsilon$
\State \textbf{Initialize:} $m_0 \gets 0$, $v_0 \gets 0$, $t \gets 0$
\While{not converged}
    \State $t \gets t + 1$
